head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > removeHeaderClass]<br/>Header Column 정보를 사용하여 특정 Header Column 에 설정된 CSS 클래스를 제거합니다.",
    "validation" : [
        "headerId(필수) 파라미터로 CSS 클래스를 제거할 Header Column 의 ID 를 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 생성 (가장 먼저)
    $c.gcm.createLabel('label="Header Column 의 ID 는 column1 ~ column4 이며, 모든 Column 이 표시됩니다."', '', 'label1');

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (기본 4행)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (Header Column ID: column1 ~ column4)
    await $c.gcm.createBasicGridView(cList);
}



scwin.btn_setHeaderClass_onclick = function () {
    let headerId = par_headerId.getValue();

    // (준비) Header Column ID 로 th 요소에 CSS 클래스 'cRed cBlue' 설정
    target1.setHeaderClass(headerId, "cRed cBlue");
    wf_body_bottom.getObj("scwin").setReturnValue("setHeaderClass(" + headerId + ", cRed cBlue)");

    // 설정 확인 - getHeaderClass 와 th className 둘 다 출력
    let rtn = target1.getHeaderClass(headerId);
    wf_body_bottom.getObj("scwin").setReturnValue("getHeaderClass(" + headerId + ") : " + rtn);

    let th = document.querySelector("th[data-header_id='" + headerId + "'], th[header_id='" + headerId + "']");
    if (th) {
        wf_body_bottom.getObj("scwin").setReturnValue("th className : " + th.className);
    }
}



scwin.btn_removeHeaderClass_onclick = function () {
    let headerId = par_headerId.getValue();
    let className = par_className.getText();

    // Header Column ID 로 th 요소에 설정된 CSS 클래스 제거
    target1.removeHeaderClass(headerId, className);
    wf_body_bottom.getObj("scwin").setReturnValue("removeHeaderClass(" + headerId + ", " + className + ")");

    // 제거 확인 - getHeaderClass 와 th className 둘 다 출력 (store/th 비대칭 가능)
    let rtn = target1.getHeaderClass(headerId);
    wf_body_bottom.getObj("scwin").setReturnValue("getHeaderClass(" + headerId + ") : " + rtn);

    let th = document.querySelector("th[data-header_id='" + headerId + "'], th[header_id='" + headerId + "']");
    if (th) {
        wf_body_bottom.getObj("scwin").setReturnValue("th className : " + th.className);
    }
}
